#!/usr/bin/env python
"""Task B - mainline-constrained interchange completion: fix the anchor mainline and let the model complete the ramps. The mainline is coarsened into known coarse-graph segments; ramp segments are generated by masked latent replacement in the coarse latent; the mainline block is hard-locked and uncoarsened into the full adjacency A; then the attribute stage jointly generates ramp coordinates + attributes while the mainline node latent is preserved via masked latent replacement at every denoising step and hard-overwritten with the anchor values."""
import os, argparse, random, logging, yaml, numpy as np, torch
import lgd  # noqa register modules/encoders/datasets
from torch_geometric.data import Data, Batch
from torch_geometric.graphgym.config import cfg
from generate_interchange_cond import (_reset_load_cfg, _build_model, _scan_meta, _build_id2idx, _prepare_infer_cfg, _load_train_ystats,
                                        _apply_transforms, _denorm_xy, _load_tpl_json, _dump_json,
                                        _feature_skeleton, _run_stage_feature, _build_node_mask, LANE_UNI_TO_NUM, SPEED_UNI_TO_MS)
from lgd.loader.dataset.interchange import lane_to_class_uni, speed_to_class_uni, N_LANE_UNI, N_SPEED_UNI
from lgd.transform.segment_graph import build_segment_graph, uncoarsen_segment_graph, _len_scale


def _split_main_ramp(tpl, ctrl_scale):                                            # split mainline/ramp: normalized xy (x ctrl_scale, dataset scale) + unified lane/speed classes + mainline adjacency mm + ramp connected components (to size the coarse-graph ramp slots)
    m_id, r_id, mxy, ml, ms = {}, {}, [], [], []
    for nd in tpl['nodes']:
        xy = [nd['x'] * ctrl_scale, nd['y'] * ctrl_scale]
        lu = lane_to_class_uni(int(nd.get('num_lanes', 1))); su = speed_to_class_uni(float(nd.get('speed', 0)))
        if nd.get('node_type', 'mainline') == 'mainline': m_id[nd['id']] = len(mxy); mxy.append(xy); ml.append(lu); ms.append(su)
        else: r_id[nd['id']] = len(r_id)
    M, R = len(mxy), len(r_id)
    mm = np.zeros((M, M), np.int64); rr = np.zeros((R, R), np.int64)
    for e in tpl.get('edges', []):
        s, t = e['source'], e['target']
        if s in m_id and t in m_id: i, j = m_id[s], m_id[t]; mm[i, j] = mm[j, i] = 1
        elif s in r_id and t in r_id: i, j = r_id[s], r_id[t]; rr[i, j] = rr[j, i] = 1
    chains, seen = [], set()                                                       # ramp connected components via BFS (rr only): count used to size coarse-graph ramp slots
    for r0 in range(R):
        if r0 in seen: continue
        stk, comp = [r0], []
        while stk:
            u = stk.pop()
            if u in seen: continue
            seen.add(u); comp.append(u)
            for v in range(R):
                if rr[u, v] and v not in seen: stk.append(v)
        chains.append(comp)
    return dict(M=M, R=R, main_xy_n=np.asarray(mxy, np.float64) if M else np.zeros((0, 2)), main_lane_uni=ml, main_speed_uni=ms, mm=mm, ramp_chains=chains)


def _coarsen_anchor_mainline(anc):                                               # coarsen the anchor mainline into known coarse segments (mainline anchoring): returns (seg_x, W_main, m_main, main_orig_ids[sum L], main_seg_lens)
    M = int(anc['M'])
    sg = build_segment_graph(torch.tensor(anc['main_xy_n'], dtype=torch.float), torch.tensor(anc['mm'], dtype=torch.long), torch.zeros(M, dtype=torch.long))  # mainline nodes are all type 0
    m = int(sg['seg_num_nodes'].item()); W = sg['seg_adj_flat'].reshape(m, m).long()
    return sg['seg_x'], W, m, sg['seg_chain_flat'].long(), sg['seg_chain_lens'].long()


def _ramp_placeholder_seg_x(m_ramp, C):                                          # ramp segment placeholder features [m_ramp, 1+C]: length prior 1 / type ramp one-hot; latent is masked to noise so the values do not affect the output
    sx = torch.zeros(m_ramp, 1 + C); sx[:, 0] = 1.0 / _len_scale(); sx[:, 2 if C >= 2 else 1] = 1.0
    return sx


def _build_partial_coarse(seg_x_main, W_main, m_main, m_ramp, target, y_mean, y_std):  # assemble a partial coarse-graph Data: known mainline segments [0:m_main] + ramp slots, W with mainline block only; transformed then fed to the topology RePaint
    C = seg_x_main.shape[1] - 1; M = m_main + m_ramp
    seg_x = torch.cat([seg_x_main, _ramp_placeholder_seg_x(m_ramp, C)], dim=0)
    W = torch.zeros(M, M, dtype=torch.long); W[:m_main, :m_main] = W_main         # ramp connectivity unknown = 0, generated by diffusion
    ei = W.nonzero(as_tuple=False).t().contiguous().long()
    nt = torch.cat([torch.zeros(m_main, dtype=torch.long), torch.ones(m_ramp, dtype=torch.long)])
    d = Data(x=seg_x, edge_index=ei, edge_attr=torch.ones(ei.shape[1], dtype=torch.long), node_type=nt,
             pos_orig=torch.zeros(M, 2), adj_flat=W.flatten().float(), num_node_per_graph=torch.tensor(M, dtype=torch.long),
             y=torch.tensor([target], dtype=torch.float), y_mean=torch.as_tensor(y_mean).float().reshape(1, -1), y_std=torch.as_tensor(y_std).float().reshape(1, -1))
    return _apply_transforms(d)


def _seg_repaint_mask(m_main, M, B, hid, device):                               # segment-level RePaint mask [B*M + B*M^2, hid]: mainline segment nodes / mainline edge block = 1 (known/anchored), rest = 0 (generated); layout matches img=cat([x, edge_attr])
    nm = torch.zeros(M); nm[:m_main] = 1.0
    em = torch.zeros(M * M); ii = torch.arange(M)
    em[((ii.unsqueeze(1) < m_main) & (ii.unsqueeze(0) < m_main)).flatten()] = 1.0
    return torch.cat([nm.repeat(B), em.repeat(B)]).to(device).unsqueeze(-1).expand(-1, hid).contiguous()


@torch.no_grad()
def _run_stage_topo_complete(model, tasks, seg_x_main, W_main, m_main, main_seg_lens, main_orig_ids, m_ramp, y_mean, y_std, device, bs, ddim_steps, ddim_eta, use_ddpm_steps, noise_temp):  # mainline anchoring + ramp coarse-graph RePaint -> hard-lock mainline block -> uncoarsen to A; tasks=[(ci,si,target)] -> [(ci,si,tg,full_adj,full_nt,main_orig_ids)]
    out, hid, M = [], int(cfg.diffusion.hid_dim), m_main + m_ramp
    for s in range(0, len(tasks), bs):
        grp = tasks[s:s + bs]
        dl = [_build_partial_coarse(seg_x_main, W_main, m_main, m_ramp, tg, y_mean, y_std) for (_, _, tg) in grp]
        batch = Batch.from_data_list(dl).to(device)
        mask = _seg_repaint_mask(m_main, M, len(grp), hid, device)
        _, gp = model.inference(batch, ddim_steps=ddim_steps, ddim_eta=ddim_eta, use_ddpm_steps=use_ddpm_steps, mask=mask, noise_temp=noise_temp)
        for (ci, si, tg), item in zip(grp, gp):
            W = item[1].clone(); meta = item[3]; lens = meta['lens_pred'].clone(); typ = meta['type_pred'].clone()
            W[:m_main, :m_main] = W_main; lens[:m_main] = main_seg_lens.to(lens.dtype); typ[:m_main] = 0  # hard-lock mainline: segment lengths/types/connectivity = anchor truth so uncoarsened mainline nodes align exactly
            full_adj, full_nt = uncoarsen_segment_graph(W, lens, typ)
            out.append((ci, si, list(tg), full_adj.long(), full_nt.long(), main_orig_ids))
        logging.info(f'[TopoComplete] {s + len(grp)}/{len(tasks)} N0={out[-1][3].shape[0]} M={M}(main{m_main}+ramp{m_ramp})')
    return out


def _topo_complete_skeleton(anc, full_adj, full_nt, main_orig_ids, target, y_mean, y_std):  # attribute-stage skeleton from the completed topology: mainline nodes [0:sum L] carry anchor xy/lanes/speed (masked-replacement reference + hard-overwrite), ramp nodes are placeholders (generated)
    N = int(full_adj.shape[0]); n_main = int(main_orig_ids.shape[0])
    xu = torch.zeros(N, 2 + N_LANE_UNI + N_SPEED_UNI)
    mo = main_orig_ids.tolist(); mxy = torch.tensor(anc['main_xy_n'], dtype=torch.float)
    ml = list(anc['main_lane_uni']); ms = list(anc['main_speed_uni'])
    for k in range(min(n_main, N)):
        oid = int(mo[k]); xu[k, :2] = mxy[oid]                                     # uncoarsened mainline node k <-> anchor original node oid (chain order)
        xu[k, 2 + int(ml[oid])] = 1.0; xu[k, 2 + N_LANE_UNI + int(ms[oid])] = 1.0
    return _feature_skeleton(full_adj, full_nt, target, y_mean, y_std, x_unified=xu)


def main():
    pa = argparse.ArgumentParser()
    pa.add_argument('--cfg', required=True)
    pa.add_argument('--targets', default=None, help='"c1,t1;c2,t2" overrides cfg.targets')
    pa.add_argument('--anchor-template', required=True, help='gid of the fixed mainline source (mainline xy + adjacency + merge/diverge positions preserved)')
    pa.add_argument('--topo-ramp-seg', type=int, default=0, help='number of ramp segment slots m_ramp (coarse-graph segments to generate); 0 = estimate from anchor ramp components x2')
    pa.add_argument('--k', type=int, default=None, help='samples per target (overrides cfg.total_per_target)')
    pa.add_argument('--batch-size', type=int, default=None, help='overrides cfg.batch_size (lower it on small devices)')
    pa.add_argument('--noise-temp', type=float, default=1.0, help='initial randn multiplier (>1 amplifies ramp initial noise for diversity)')
    pa.add_argument('--out', default=None)
    a = pa.parse_args()
    with open(a.cfg, 'r', encoding='utf-8') as f: gc = yaml.safe_load(f)['generate']
    if a.targets: gc['targets'] = [[float(v) for v in p.split(',')] for p in a.targets.split(';')]
    if a.batch_size is not None: gc['batch_size'] = int(a.batch_size)
    if a.out: gc['out_dir'] = a.out
    random.seed(gc['seed']); np.random.seed(gc['seed']); torch.manual_seed(gc['seed'])
    logging.basicConfig(level=logging.INFO, format='%(asctime)s %(levelname)s %(message)s')
    os.makedirs(gc['out_dir'], exist_ok=True)

    ids_all, ys_all, Ns_all = _scan_meta(gc['meta_cache'], gc['graph_data_dir'])   # anchor mainline source (four-leg subset)
    _reset_load_cfg(gc['attribute_cfg']); _prepare_infer_cfg(gc['graph_data_dir'])
    max_n = cfg.dataset.get('max_nodes', 200); ctrl_scale = float(cfg.dataset.get('ctrl_scale', 1.0))
    id2idx = _build_id2idx(ids_all, Ns_all, max_n, seed=gc['seed'])
    y_mean, y_std = _load_train_ystats(gc.get('train_stats_dir', gc['graph_data_dir']))  # normalization from training statistics
    diag = float(gc['global_diag']); denorm_on = bool(gc.get('denorm', True))
    anc_gid = str(a.anchor_template)
    if anc_gid not in id2idx: raise SystemExit(f'anchor_gid={anc_gid} not in id2idx (filtered by max_nodes or missing)')
    anc_tpl = _load_tpl_json(anc_gid, gc['graph_data_dir']); anc = _split_main_ramp(anc_tpl, ctrl_scale)
    K = int(a.k) if a.k is not None else int(gc.get('total_per_target', 1))

    seg_x_main, W_main, m_main, main_orig_ids, main_seg_lens = _coarsen_anchor_mainline(anc)  # 1. coarsen mainline into known segments
    m_ramp = int(a.topo_ramp_seg) if a.topo_ramp_seg > 0 else max(2, len(anc['ramp_chains']) * 2)
    tasks = [(ci, si, list(tg)) for ci, tg in enumerate(gc['targets']) for si in range(K)]
    logging.info(f'[Complete] anchor={anc_gid} M={anc["M"]} m_main={m_main} m_ramp={m_ramp} K={K} total={len(tasks)}')

    mt = _build_model(gc['topology_cfg'], gc['topology_ckpt']); device = torch.device(cfg.accelerator)  # 2. ramp topology RePaint completion
    topo_recs = _run_stage_topo_complete(mt, tasks, seg_x_main, W_main, m_main, main_seg_lens, main_orig_ids, m_ramp,
                                         y_mean, y_std, device, gc['batch_size'], gc.get('ddim_steps'), gc.get('ddim_eta', 0.0), gc.get('use_ddpm_steps', False), float(a.noise_temp))
    del mt; torch.cuda.empty_cache()

    mf = _build_model(gc['attribute_cfg'], gc['attribute_ckpt']); device = torch.device(cfg.accelerator)  # 3. attribute stage: mainline anchored (RePaint) + ramp coordinates/attributes generated
    ctrl_scale = float(cfg.dataset.get('ctrl_scale', ctrl_scale))
    skels = [_topo_complete_skeleton(anc, fa, fn, mo, tg, y_mean, y_std) for (_, _, tg, fa, fn, mo) in topo_recs]
    feat = _run_stage_feature(mf, skels, device, gc['batch_size'], gc.get('ddim_steps'), gc.get('ddim_eta', 0.0), gc.get('use_ddpm_steps', False), lock_mainline=True, noise_temp=float(a.noise_temp))
    del mf; torch.cuda.empty_cache()

    summary_p = os.path.join(gc['out_dir'], '_summary.csv')                        # 4. de-normalize + write JSON
    with open(summary_p, 'w', encoding='utf-8') as fsum:
        fsum.write('case,sample,target_cost,target_throughput,anchor_gid,M_main,R_ramp,N,lanes_mean,speed_mean_ms\n')
        for (ci, si, tg, _, _, _), (xy, adj, lu, su, ntype) in zip(topo_recs, feat):
            num_lanes = np.array([LANE_UNI_TO_NUM(c) for c in lu]); speed_ms = np.array([SPEED_UNI_TO_MS(c) for c in su])
            M_ = int((ntype == 0).sum()); R_ = int((ntype == 1).sum())
            pos_m = _denorm_xy(xy, ctrl_scale, diag)
            sub = os.path.join(gc['out_dir'], f'anc{anc_gid}_c{int(tg[0])}_t{int(tg[1])}'); os.makedirs(sub, exist_ok=True)
            base = os.path.join(sub, f'{si:04d}')
            _dump_json(base + '.json', anc_tpl, pos_m, xy.numpy() / ctrl_scale, adj, num_lanes, speed_ms, tg, gc['z_fill'], diag, denorm_on, gen_ntype=ntype.astype(np.int64))
            fsum.write(f'{ci},{si},{tg[0]:.2f},{tg[1]:.2f},{anc_gid},{M_},{R_},{xy.shape[0]},{float(num_lanes.mean()):.2f},{float(speed_ms.mean()):.2f}\n')
    logging.info(f'[Done] {len(feat)} samples -> {gc["out_dir"]} (summary: {summary_p})')


if __name__ == '__main__':
    main()
